"""NcclientWrapper module"""
from ncclient import manager as NcclientManager

from taf.ul.oran_mplane.core.libraries.base import LibrariesBase


class NcclientWrapper(LibrariesBase):
    """NcclientWrapper class"""

    def __init__(self, manager: NcclientManager):
        super().__init__(manager)
        self.manager = manager

    def get_without_filter(self, with_defaults):
        """
        :param with_defaults:
        :return:
        """
        return self.manager.get(with_defaults=with_defaults)

    def edit_config(self, request, target, default_operation, test_option, error_option, msg_format):
        """
        :param request:
        :param target:
        :param default_operation:
        :param test_option:
        :param error_option:
        :param msg_format:
        :return:
        """
        return self.manager.edit_config(
            config=request,
            target=target,
            default_operation=default_operation,
            test_option=test_option,
            error_option=error_option,
            format=msg_format,
        )

    def get_xpath(self, msg_filter, with_defaults):
        """
        :param msg_filter:
        :param with_defaults:
        :return:
        """
        return self.manager.get(msg_filter, with_defaults=with_defaults)

    def get_subtree(self, content, with_defaults):
        """
        :param content:
        :param with_defaults:
        :return:
        """
        return self.manager.get(filter=("subtree", content), with_defaults=with_defaults)

    def create_subscription(self, noti_filter, stream_name, start_time, stop_time):
        """
        :param noti_filter:
        :param stream_name:
        :param start_time:
        :param stop_time:
        :return:
        """
        return self.manager.create_subscription(
            filter=noti_filter, stream_name=stream_name, start_time=start_time, stop_time=stop_time
        )

    def take_notification(self):
        """
        :return:
        """
        return self.manager.take_notification(block=False, timeout=None)

    def get_config(self, source):
        """
        :param source:
        :return:
        """
        return self.manager.get_config(source)

    def server_capabilities(self):
        """
        :return:
        """
        return list(self.manager.server_capabilities)

    def client_capabilities(self,):
        """
        :return:
        """
        return list(self.manager.client_capabilities)

    def send_rpc(self, msg):
        """
        :param msg:
        :return:
        """
        return self.manager.rpc(msg, source=None, filter=None, config=None, target=None, format=None)

    def get_session_id(self, *_, **kwargs) -> int:
        """
        Returns session id
        :return: int, session id
        """
        return self.manager.session_id

    def kill_session(self, session_id):
        """
        Kills specified session        :param session_id:
        :return:
        """
        session_id = str.encode(str(session_id))
        return self.manager.kill_session(session_id=session_id)
